import com.tfamistaketracker.detector.tracker.VengeanceTracker;
import lombok.Getter;
import lombok.NonNull;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GraphicsObject;
import net.runelite.api.Projectile;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;

import javax.inject.Inject;
import java.util.List;
import java.util.Set;

/**
 * Interface for detecting mistakes during The Fractured Archives
 */
public abstract class BaseMistakeDetector {

    protected static final int CYCLES_PER_GAME_TICK = Constants.GAME_TICK_LENGTH / Constants.CLIENT_TICK_LENGTH;

    @Inject
    protected Client client;

    @Inject
    protected EventBus eventBus;

    @Inject
    protected RaidState raidState;

    @Inject
    protected VengeanceTracker vengeanceTracker;

    @Getter
    private boolean started;

    /**
     * Used to tell a detector to start listening for events.
     */
    public void startup() {
        if (started) return;

        started = true;
        cleanup();
        eventBus.register(this);
    }

    /**
     * Shutdown and cleanup state. This is always called when the plugin is shutdown, or when a detector is finished.
     */
    public void shutdown() {
        started = false;
        eventBus.unregister(this);
        cleanup();
    }

    /**
     * Cleanup all relevant state in the detector. This is called during startup to reset state, and shutdown to cleanup.
     */
    public abstract void cleanup();

    /**
     * Retrieve the raid room that this detector should startup in. A null value means *all* rooms
     *
     * @return The raid room that the detector should startup in, or null for *all* rooms
     */
    public abstract RaidRoom getRaidRoom();

    /**
     * Retrieve the id of the NPC that must be spawned for this detector to startup, on top of being in its raid room.
     * A null value means no NPC is required.
     *
     * @return The id of the NPC that the detector requires, or null for none
     */
    public Integer getRequiredNpcId() {
        return null;
    }

    /**
     * Detects mistakes for the given raider.
     * This is called during handling the {@link net.runelite.api.events.GameTick} event, each tick.
     *
     * @param raider - The raider to detect mistakes for
     * @return The list of {@link TfaMistake} detected on this tick
     */
    public abstract List<TfaMistake> detectMistakes(@NonNull Raider raider);

    /**
     * This method allows detectors to handle some logic after all detectMistakes methods have been invoked
     * for this {@link net.runelite.api.events.GameTick}. Commonly, this is to cleanup state from after this tick.
     */
    public abstract void afterDetect();

    /**
     * Determines whether or not this detector is currently detecting mistakes. Commonly this is by checking the current
     * {@link RaidRoom} in the {@link RaidState}
     *
     * @return True if the detector is detecting mistakes, else false
     */
    public boolean isDetectingMistakes() {
        if (getRaidRoom() == null) { // null means *all* rooms
            return raidState.isInRaid();
        }

        return raidState.getCurrentRoom() == getRaidRoom();
    }

    protected WorldPoint getWorldPoint(Actor actor) {
        return WorldPoint.fromLocal(client, actor.getLocalLocation());
    }

    protected WorldPoint getWorldPoint(GraphicsObject graphicsObject) {
        return WorldPoint.fromLocal(client, graphicsObject.getLocation());
    }

    /**
     * Computes the WorldPoints in the given area, expanded outward by the given number of tiles in every direction.
     * For example, a 1x1 area with an expansion of 1 is the 3x3 area centred on it.
     *
     * @param area             The area, e.g. an NPC's footprint
     * @param tilesToExpandBy The number of tiles to expand the area outward by
     * @return The set of WorldPoints in the expanded area
     */
    protected Set<WorldPoint> computeTilesAround(WorldArea area, int tilesToExpandBy) {
        return ImmutableSet.copyOf(new WorldArea(area.getX() - tilesToExpandBy, area.getY() - tilesToExpandBy,
                area.getWidth() + 2 * tilesToExpandBy, area.getHeight() + 2 * tilesToExpandBy,
                area.getPlane()).toWorldPointList());
    }

    /**
     * Computes the WorldPoints within the given number of tiles of the center, e.g. 1 tile is the 3x3 centred on it.
     *
     * @param center          The center tile
     * @param tilesToExpandBy The number of tiles to expand outward from the center by
     * @return The set of WorldPoints around and including the center
     */
    protected Set<WorldPoint> computeTilesAround(WorldPoint center, int tilesToExpandBy) {
        return computeTilesAround(new WorldArea(center, 1, 1), tilesToExpandBy);
    }

    /**
     * Calculates and retrieves the activation tick for the specified GraphicsObject based on the start cycle and
     * the given hit delay.
     *
     * @param graphicsObject The graphics object
     * @param hitDelay       The delay in ticks from when the graphics object animation starts and when it causes a hit
     * @return The activation tick for when the graphics object will denote a hit on the player
     */
    protected int getActivationTick(GraphicsObject graphicsObject, int hitDelay) {
        int ticksToStart = (graphicsObject.getStartCycle() - client.getGameCycle()) / CYCLES_PER_GAME_TICK;
        return client.getTickCount() + ticksToStart + hitDelay; // Add the hit delay for how long between start to hit
    }

    /**
     * Calculates and retrieves the activation tick for the specified Projectile based on the remaining cycles.
     *
     * @param projectile The projectile object
     * @return The activation tick for when the projectile object will reach its target
     */
    protected int getActivationTick(Projectile projectile) {
        int ticksRemaining = projectile.getRemainingCycles() / CYCLES_PER_GAME_TICK;
        return client.getTickCount() + ticksRemaining;
    }
}

package com.tfamistaketracker.detector;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.collect.HashMultiset;
import com.google.common.collect.Multiset;
import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.RaidState;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.boss.ArchiveGuardianDetector;
import com.tfamistaketracker.detector.boss.BorkDetector;
import com.tfamistaketracker.detector.boss.DreadnothDetector;
import com.tfamistaketracker.detector.boss.OcellusP1Detector;
import com.tfamistaketracker.detector.boss.OcellusP2Detector;
import com.tfamistaketracker.detector.boss.OcellusP3Detector;
import com.tfamistaketracker.detector.boss.XarthDetector;
import com.tfamistaketracker.detector.death.DeathDetector;
import com.tfamistaketracker.detector.tracker.BaseRaidTracker;
import com.tfamistaketracker.detector.tracker.VengeanceTracker;
import com.tfamistaketracker.events.RaidRoomChanged;
import lombok.Getter;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Manager for all the {@link BaseMistakeDetector}. It keeps all the detectors in memory in order to manage events.
 * <p>
 * All detectors initialized in the manager are responsible for determining when to start detecting mistakes.
 * The manager may call the startup() or shutdown() method on a detector at any time.
 * <p>
 * When the manager is on (started = true), then all other detectors are subscribed to the EventBus and
 * listening for events on when to turn themselves on/off. This will only be true while the player is in TFA.
 */
@Slf4j
@Singleton
public class MistakeDetectorManager {

    private final Client client;
    private final EventBus eventBus;
    private final RaidState raidstate;
    private final VengeanceTracker vengeanceTracker;

    @Getter
    private final List<BaseRaidTracker> raidTrackers;

    @Getter
    private final List<BaseMistakeDetector> mistakeDetectors;

    @Getter
    @VisibleForTesting
    private boolean started;

    // How many of each NPC id that some detector requires are currently spawned
    private final Multiset<Integer> requiredNpcCounts = HashMultiset.create();

    @Inject
    public MistakeDetectorManager(Client client,
                                  EventBus eventBus,
                                  RaidState raidState,
                                  VengeanceTracker vengeanceTracker,
                                  ArchiveGuardianDetector archiveGuardianDetector,
                                  BorkDetector borkDetector,
                                  DreadnothDetector dreadnothDetector,
                                  XarthDetector xarthDetector,
                                  OcellusP1Detector ocellusP1Detector,
                                  OcellusP2Detector ocellusP2Detector,
                                  OcellusP3Detector ocellusP3Detector,
                                  DeathDetector deathDetector) {
        this.raidTrackers = Arrays.asList(vengeanceTracker);

        // Order matters, since it's last write wins for which mistake gets put on overhead text. Death should be last.
        this.mistakeDetectors = new ArrayList<>(Arrays.asList(
                archiveGuardianDetector,
                borkDetector,
                dreadnothDetector,
                xarthDetector,
                ocellusP1Detector,
                ocellusP2Detector,
                ocellusP3Detector,
                deathDetector
        ));

        this.client = client;
        this.eventBus = eventBus;
        this.raidstate = raidState;
        this.vengeanceTracker = vengeanceTracker;
        this.started = false;
    }

    public void startup() {
        started = true;
        eventBus.register(this);

        // Startup all raid trackers
        raidTrackers.forEach(BaseRaidTracker::startup);

        requiredNpcCounts.clear();
        for (NPC npc : client.getTopLevelWorldView().npcs()) {
            addNpc(npc.getId());
        }

        // The first room is entered before the manager starts listening for room changes
        refreshDetectors(raidstate.getCurrentRoom());
    }

    public void shutdown() {
        mistakeDetectors.forEach(BaseMistakeDetector::shutdown);
        // Don't clear mistakeDetectors or else we can't get them back.

        raidTrackers.forEach(BaseRaidTracker::shutdown);
        requiredNpcCounts.clear();

        eventBus.unregister(this);
        started = false;
    }

    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        if (!started) return Collections.emptyList();

        List<TfaMistake> mistakes = new ArrayList<>();
        for (BaseMistakeDetector mistakeDetector : mistakeDetectors) {
            if (mistakeDetector.isStarted() && mistakeDetector.isDetectingMistakes() && !raider.isDead()) {
                try {
                    mistakes.addAll(mistakeDetector.detectMistakes(raider));
                } catch (RuntimeException e) {
                    onError(mistakeDetector, e);
                }
            }
        }

        return mistakes;
    }

    public void afterDetect() {
        if (!started) return;

        for (BaseRaidTracker raidTracker : raidTrackers) {
            try {
                raidTracker.afterDetect();
            } catch (RuntimeException e) {
                onError(raidTracker, e);
            }
        }

        for (BaseMistakeDetector mistakeDetector : mistakeDetectors) {
            if (mistakeDetector.isStarted() && mistakeDetector.isDetectingMistakes()) {
                try {
                    mistakeDetector.afterDetect();
                } catch (RuntimeException e) {
                    onError(mistakeDetector, e);
                }
            }
        }
    }

    // Catch per detector so one broken detector can't stop the others, or the raiders' locations from updating
    private void onError(Object source, RuntimeException e) {
        log.warn("{} threw an exception", source.getClass().getSimpleName(), e);
    }

    @Subscribe
    public void onRaidRoomChanged(RaidRoomChanged event) {
        refreshDetectors(event.getNewRaidRoom());
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        if (addNpc(event.getNpc().getId())) {
            refreshDetectors(raidstate.getCurrentRoom());
        }
    }

    @Subscribe
    public void onNpcChanged(NpcChanged event) {
        boolean removed = event.getOld() != null && removeNpc(event.getOld().getId());
        if (addNpc(event.getNpc().getId()) || removed) {
            refreshDetectors(raidstate.getCurrentRoom());
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        if (removeNpc(event.getNpc().getId())) {
            refreshDetectors(raidstate.getCurrentRoom());
        }
    }

    private boolean addNpc(int npcId) {
        if (!isRequiredNpc(npcId)) return false;
        requiredNpcCounts.add(npcId);
        return true;
    }

    private boolean removeNpc(int npcId) {
        if (!isRequiredNpc(npcId)) return false;
        requiredNpcCounts.remove(npcId);
        return true;
    }

    private boolean isRequiredNpc(int npcId) {
        return mistakeDetectors.stream().anyMatch(d -> d.getRequiredNpcId() != null && d.getRequiredNpcId() == npcId);
    }

    private void refreshDetectors(RaidRoom room) {
        for (BaseMistakeDetector detector : mistakeDetectors) {
            if (shouldBeStarted(detector, room)) {
                detector.startup();
            } else if (detector.isStarted()) {
                detector.shutdown();
            }
        }
    }

    private boolean shouldBeStarted(BaseMistakeDetector detector, RaidRoom room) {
        // A null room means *all* rooms
        if (detector.getRaidRoom() != null && detector.getRaidRoom() != room) return false;
        return detector.getRequiredNpcId() == null || requiredNpcCounts.contains(detector.getRequiredNpcId());
    }

}

package com.tfamistaketracker.detector.boss;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.BaseMistakeDetector;
import com.tfamistaketracker.detector.tracker.DelayedHitTilesTracker;
import com.tfamistaketracker.detector.tracker.InstantHitTilesTracker;
import com.tfamistaketracker.detector.tracker.OverheadTracker;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.HeadIcon;
import net.runelite.api.NPC;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.ARCHIVE_GUARDIAN;
import static com.tfamistaketracker.TfaMistake.ARCHIVE_GUARDIAN_MELEE;
import static com.tfamistaketracker.TfaMistake.ARCHIVE_GUARDIAN_MUSHROOM;
import static com.tfamistaketracker.TfaMistake.ARCHIVE_GUARDIAN_RANGE;
import static com.tfamistaketracker.TfaMistake.ARCHIVE_GUARDIAN_FALL;
import static com.tfamistaketracker.TfaMistake.ARCHIVE_GUARDIAN_VINE;

/**
 * The Archive Guardian alternates between flying and grounded. When he drops down, he damages anyone under him or
 * within melee distance. While flying, he melees anyone under him.
 * <p>
 * Mushrooms explode over a 3x3 area when someone gets close, poisoning anyone still in it a tick later. Vines hit
 * everything adjacent to them on the tick they swipe.
 */
@Slf4j
@Singleton
public class ArchiveGuardianDetector extends BaseMistakeDetector {

    private static final Set<Integer> GUARDIAN_IDS = ImmutableSet.of(NpcID.TFA_GUARDIAN,
            NpcID.TFA_GUARDIAN_UNSHIELDED);

    private static final Map<Integer, OverheadTracker.Attack> RANGE_ATTACKS = ImmutableMap.of(
            SpotanimID.VFX_GUARDIAN_RANGED_PROJANIM01,
            OverheadTracker.Attack.of(HeadIcon.RANGED, OverheadTracker.PrayerCheck.ANIMATION));

    private static final int FALL_DISTANCE = 1;
    private static final int VINE_DISTANCE = 1;
    private static final int MUSHROOM_DISTANCE = 1;
    private static final int MELEE_HIT_DELAY_IN_TICKS = 1;
    private static final int MUSHROOM_HIT_DELAY_IN_TICKS = 1;

    // Overheads are only final on GameTick, since NPC animations can fire before player updates within a tick
    private NPC rangeAttacker;
    // Nothing in the room hurts once the guardian starts dying
    private boolean isGuardianDead;

    private final InstantHitTilesTracker fallHitTiles = new InstantHitTilesTracker();
    private final DelayedHitTilesTracker meleeHitTiles = new DelayedHitTilesTracker();
    private final OverheadTracker rangeOverheadTracker = new OverheadTracker(RANGE_ATTACKS);
    private final DelayedHitTilesTracker mushroomHitTiles = new DelayedHitTilesTracker();
    private final InstantHitTilesTracker vineHitTiles = new InstantHitTilesTracker();

    public ArchiveGuardianDetector() {
        rangeAttacker = null;
        isGuardianDead = false;
    }

    @Override
    public void cleanup() {
        isGuardianDead = false;
        clearTrackers();
    }

    private void clearTrackers() {
        rangeAttacker = null;
        fallHitTiles.clear();
        meleeHitTiles.clear();
        rangeOverheadTracker.clear();
        mushroomHitTiles.clear();
        vineHitTiles.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return ARCHIVE_GUARDIAN;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        if (isGuardianDead) {
            return mistakes;
        }

        if (fallHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(ARCHIVE_GUARDIAN_FALL);
        }

        if (meleeHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation()) &&
                !vengeanceTracker.didPopVengeance(raider)) {
            mistakes.add(ARCHIVE_GUARDIAN_MELEE);
        }

        if (isRangeHit(raider)) {
            mistakes.add(ARCHIVE_GUARDIAN_RANGE);
        }

        if (mushroomHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(ARCHIVE_GUARDIAN_MUSHROOM);
        }

        if (vineHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(ARCHIVE_GUARDIAN_VINE);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
    }

    private boolean isRangeHit(Raider raider) {
        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return rangeOverheadTracker.didMissPrayer(raider);
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        fallHitTiles.onGameTick(client.getTickCount());
        meleeHitTiles.onGameTick(client.getTickCount());
        rangeOverheadTracker.onGameTick(client.getTickCount());
        if (rangeAttacker != null) {
            rangeOverheadTracker.snapshotOverheads(rangeAttacker, raidState.getRaiders().values());
        }
        rangeAttacker = null;
        mushroomHitTiles.onGameTick(client.getTickCount());
        vineHitTiles.onGameTick(client.getTickCount());
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC) || isGuardianDead) return;

        NPC npc = (NPC) actor;
        if (GUARDIAN_IDS.contains(npc.getId())) {
            if (npc.getAnimation() == AnimationID.NPC_ARCHIVE_GUARDIAN_DEATH01) {
                onGuardianDeath();
            } else if (npc.getAnimation() == AnimationID.NPC_ARCHIVE_GUARDIAN_IDLE_TO_GROUND01) {
                computeTilesAround(npc.getWorldArea(), FALL_DISTANCE).forEach(fallHitTiles::add);
            } else if (npc.getAnimation() == AnimationID.NPC_ARCHIVE_GUARDIAN_RANGE_ATTACK01) {
                rangeAttacker = npc;
            } else if (npc.getAnimation() == AnimationID.NPC_ARCHIVE_GUARDIAN_MELEE_ATTACK01) {
                meleeHitTiles.putAll(client.getTickCount() + MELEE_HIT_DELAY_IN_TICKS,
                        computeTilesAround(npc.getWorldArea(), 0));
            }
        } else if (npc.getId() == NpcID.ARCHIVE_GUARDIAN_TENTACLE &&
                npc.getAnimation() == AnimationID.NPC_GUARDIAN_ARCHIVE_TENTACLE_ATTACK01) {
            computeTilesAround(actor.getWorldArea(), VINE_DISTANCE).forEach(vineHitTiles::add);
        }
    }

    @Subscribe
    public void onProjectileMoved(ProjectileMoved event) {
        if (!RANGE_ATTACKS.containsKey(event.getProjectile().getId()) || isGuardianDead) return;

        rangeOverheadTracker.trackProjectile(event, client.getTickCount());
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_GUARDIAN_MUSHROOM_DESPAWN && !isGuardianDead) {
            mushroomHitTiles.putAll(client.getTickCount() + MUSHROOM_HIT_DELAY_IN_TICKS,
                    computeTilesAround(event.getGameObject().getWorldLocation(), MUSHROOM_DISTANCE));
        }
    }

    @Subscribe
    public void onNpcChanged(NpcChanged event) {
        if (event.getNpc().getId() == NpcID.TFA_GUARDIAN_DEAD) {
            onGuardianDeath();
        }
    }

    private void onGuardianDeath() {
        isGuardianDead = true;
        clearTrackers();
    }
}

