/**
 * Bork's stomp and melee both hit the tiles marked by wave dust graphics on the tick they appear. The stomp sends
 * several waves while he's stomping, and his melee hits twice. Melee prayer reduces the melee but not the stomp.
 * <p>
 * The Smorks fire ranged and magic projectiles that need the matching prayer when they hit. Their fireballs leave
 * fire patches that last until Bork dies and burn anyone standing on them.
 */
@Slf4j
@Singleton
public class BorkDetector extends BaseMistakeDetector {

    private static final Set<Integer> STOMP_ANIMATION_IDS = ImmutableSet.of(
            AnimationID.NPC_BORK_ENRAGED_STOMP_ATTACK_IN01,
            AnimationID.NPC_BORK_ENRAGED_STOMP_ATTACK01,
            AnimationID.NPC_BORK_ENRAGED_STOMP_ATTACK_CYCLE_AND_OUT01);

    private static final Set<Integer> FIREBALL_SPLASH_IDS = ImmutableSet.of(
            SpotanimID.VFX_SMORK_NAPALM_FIRE_SPOTANIM01,
            SpotanimID.VFX_SMORK_NAPALM_SPLAT_SPOTANIM01,
            SpotanimID.VFX_SMORK_NAPALM_SPLAT_SPOTANIM01_90,
            SpotanimID.VFX_SMORK_NAPALM_SPLAT_SPOTANIM01_180,
            SpotanimID.VFX_SMORK_NAPALM_SPLAT_SPOTANIM01_270);

    private static final Map<Integer, OverheadTracker.Attack> SMORKS_ATTACKS = ImmutableMap.of(
            SpotanimID.VFX_SMORK_RANGE_ATTACK_PROJANIM01,
            OverheadTracker.Attack.of(HeadIcon.RANGED, OverheadTracker.PrayerCheck.HIT),
            SpotanimID.VFX_SMORK_MAGE_ATTACK_PROJANIM01,
            OverheadTracker.Attack.of(HeadIcon.MAGIC, OverheadTracker.PrayerCheck.HIT));

    // Bork spawns before the room is detected, so he's picked up from his animations instead of his spawn
    private NPC bork;
    private boolean isStomping;
    private int lastFootprintTick;

    private final InstantHitTilesTracker stompHitTiles = new InstantHitTilesTracker();
    private final InstantHitTilesTracker meleeHitTiles = new InstantHitTilesTracker();
    private final InstantHitTilesTracker fireballHitTiles = new InstantHitTilesTracker();
    private final OverheadTracker smorksOverheadTracker = new OverheadTracker(SMORKS_ATTACKS);
    // Fire tile -> tick it spawned. Fire doesn't burn on the tick it spawns.
    private final Map<WorldPoint, Integer> fireTiles = new HashMap<>();
    // Raiders who land in the arena mid-fight can be on the stomp or melee tiles without getting hit
    private final AppliedHitsplatsTracker appliedHitsplats = new AppliedHitsplatsTracker();

    public BorkDetector() {
        bork = null;
        isStomping = false;
        lastFootprintTick = -1;
    }

    @Override
    public void cleanup() {
        bork = null;
        isStomping = false;
        lastFootprintTick = -1;
        stompHitTiles.clear();
        meleeHitTiles.clear();
        fireballHitTiles.clear();
        smorksOverheadTracker.clear();
        fireTiles.clear();
        appliedHitsplats.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return BORK;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();

        if (isOnFire(raider.getPreviousWorldLocation())) {
            mistakes.add(BORK_FIRE);
        }

        if (fireballHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(BORK_FIREBALL);
        }

        if (stompHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation()) &&
                appliedHitsplats.popHitsplatApplied(raider.getName())) {
            mistakes.add(BORK_STOMP);
        }

        if (isMeleeHit(raider)) {
            mistakes.add(BORK_MELEE);
        }

        if (isSmorksHit(raider)) {
            mistakes.add(BORK_SMORKS_AA);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
        appliedHitsplats.clear();
    }

    private boolean isOnFire(WorldPoint location) {
        Integer spawnTick = fireTiles.get(location);
        return spawnTick != null && spawnTick != client.getTickCount();
    }

    private boolean isMeleeHit(Raider raider) {
        if (!meleeHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            return false;
        }

        if (vengeanceTracker.didPopVengeance(raider) || raider.getPlayer().getOverheadIcon() == HeadIcon.MELEE) {
            return false;
        }

        return appliedHitsplats.popHitsplatApplied(raider.getName());
    }

    private boolean isSmorksHit(Raider raider) {
        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return smorksOverheadTracker.didMissPrayer(raider);
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (!(event.getActor() instanceof Player)) return;

        int type = event.getHitsplat().getHitsplatType();
        if (type == HitsplatID.HEAL || type == HitsplatID.POISON || type == HitsplatID.VENOM ||
                type == HitsplatID.DISEASE || type == HitsplatID.BURN) return;

        appliedHitsplats.addHitsplatForRaider(event.getActor().getName());
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        stompHitTiles.onGameTick(client.getTickCount());
        meleeHitTiles.onGameTick(client.getTickCount());
        fireballHitTiles.onGameTick(client.getTickCount());
        smorksOverheadTracker.onGameTick(client.getTickCount());
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        if (FIREBALL_SPLASH_IDS.contains(event.getGraphicsObject().getId())) {
            fireballHitTiles.add(getWorldPoint(event.getGraphicsObject()));
            return;
        }
        if (event.getGraphicsObject().getId() != SpotanimID.TFA_WAVE_DUST_SHORT) return;

        InstantHitTilesTracker hitTiles = isStomping ? stompHitTiles : meleeHitTiles;
        hitTiles.add(getWorldPoint(event.getGraphicsObject()));

        // Under him isn't safe either, even though the dust doesn't show there
        if (bork != null && lastFootprintTick != client.getTickCount()) {
            lastFootprintTick = client.getTickCount();
            bork.getWorldArea().toWorldPointList().forEach(hitTiles::add);
        }
    }

    @Subscribe
    public void onProjectileMoved(ProjectileMoved event) {
        if (!SMORKS_ATTACKS.containsKey(event.getProjectile().getId())) return;

        smorksOverheadTracker.trackProjectile(event, client.getTickCount());
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_BORK_RAGGED_TILE) {
            fireTiles.put(event.getGameObject().getWorldLocation(), client.getTickCount());
        }
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_BORK_RAGGED_TILE) {
            fireTiles.remove(event.getGameObject().getWorldLocation());
        }
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        if (!(event.getActor() instanceof NPC) || ((NPC) event.getActor()).getId() != NpcID.TFA_BORK) return;

        bork = (NPC) event.getActor();
        isStomping = STOMP_ANIMATION_IDS.contains(bork.getAnimation());
    }
}

package com.tfamistaketracker.detector.boss;

import com.google.common.collect.ImmutableMap;
import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.BaseMistakeDetector;
import com.tfamistaketracker.detector.tracker.AppliedHitsplatsTracker;
import com.tfamistaketracker.detector.tracker.DelayedHitTilesTracker;
import com.tfamistaketracker.detector.tracker.OverheadTracker;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.HeadIcon;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.DREADNOTH;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_BLOOD_POOL;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_BLOOD_BALL;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_INSIDE;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_JELLY;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_LANDED;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_RANGE;
import static com.tfamistaketracker.TfaMistake.DREADNOTH_SLAM;

/**
 * Dreadnoth's jumps slam the whole room, which melee prayer blocks, except for anyone he lands on. His ranged
 * projectiles need range prayer when they hit, and his blood balls and dead jellies leave blood pools that hurt
 * anyone standing on them. Jellies melee whoever they're attacking unless they pray melee.
 */
@Slf4j
@Singleton
public class DreadnothDetector extends BaseMistakeDetector {

    private static final Map<Integer, OverheadTracker.Attack> RANGE_ATTACKS = ImmutableMap.of(
            SpotanimID.VFX_DREADNOTH_RANGED_PROJ01,
            OverheadTracker.Attack.of(HeadIcon.RANGED, OverheadTracker.PrayerCheck.HIT));

    private static final int JUMP_IN_PLACE_DURATION_IN_TICKS = 1;
    private static final int JUMP_DURATION_IN_TICKS = 3;
    private static final int LANDING_DISTANCE = 2;
    private static final int BLOOD_POOL_HIT_INTERVAL_IN_TICKS = 2;
    private static final int INSIDE_DELAY_AFTER_LANDING_IN_TICKS = 1;

    // Needed every tick for the footprint, and he spawns before the room is detected
    private NPC dreadnoth;
    private WorldArea previousDreadnothArea;
    private int landingTick;
    // Once he dies only the blood pools, jellies and his final ranged volley can still hurt anyone
    private boolean isDreadnothDead;
    private int deathTick;

    private final Set<Integer> slamTicks = new HashSet<>();
    private final Set<String> jellyTargets = new HashSet<>();
    private final OverheadTracker rangeOverheadTracker = new OverheadTracker(RANGE_ATTACKS);
    private final DelayedHitTilesTracker landingHitTiles = new DelayedHitTilesTracker();
    private final DelayedHitTilesTracker bloodBallHitTiles = new DelayedHitTilesTracker();
    private final AppliedHitsplatsTracker appliedHitsplats = new AppliedHitsplatsTracker();
    private final Set<Projectile> trackedBloodBalls = new HashSet<>();
    // Blood pool tile -> tick it spawned. Pools don't hurt on the tick they spawn.
    private final Map<WorldPoint, Integer> bloodPools = new HashMap<>();
    // Raider name -> tick they were last hurt by a blood pool. Pools can't hurt the same raider on back-to-back ticks.
    private final Map<String, Integer> lastBloodPoolHitTicks = new HashMap<>();

    public DreadnothDetector() {
        dreadnoth = null;
        previousDreadnothArea = null;
        landingTick = -1;
        isDreadnothDead = false;
    }

    @Override
    public void startup() {
        super.startup();
        for (NPC npc : client.getTopLevelWorldView().npcs()) {
            if (npc.getId() == NpcID.TFA_JELLY_BOSS) {
                dreadnoth = npc;
            }
        }
    }

    @Override
    public void cleanup() {
        dreadnoth = null;
        previousDreadnothArea = null;
        landingTick = -1;
        isDreadnothDead = false;
        slamTicks.clear();
        jellyTargets.clear();
        rangeOverheadTracker.clear();
        landingHitTiles.clear();
        bloodBallHitTiles.clear();
        trackedBloodBalls.clear();
        bloodPools.clear();
        lastBloodPoolHitTicks.clear();
        appliedHitsplats.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return DREADNOTH;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        WorldPoint previousLocation = raider.getPreviousWorldLocation();

        if (isBloodPoolHit(raider)) {
            mistakes.add(DREADNOTH_BLOOD_POOL);
        }

        if (jellyTargets.contains(raider.getName()) && raider.getPlayer().getOverheadIcon() != HeadIcon.MELEE) {
            mistakes.add(DREADNOTH_JELLY);
        }

        if (isRangeHit(raider)) {
            mistakes.add(DREADNOTH_RANGE);
        }

        if (isDreadnothDead) {
            return mistakes;
        }

        if (isInside(previousLocation)) {
            mistakes.add(DREADNOTH_INSIDE);
        }

        if (bloodBallHitTiles.getActiveHitTiles().contains(previousLocation) &&
                appliedHitsplats.popHitsplatApplied(raider.getName())) {
            mistakes.add(DREADNOTH_BLOOD_BALL);
        }

        if (landingHitTiles.getActiveHitTiles().contains(previousLocation)) {
            mistakes.add(DREADNOTH_LANDED);
        } else if (isSlamHit(raider)) {
            mistakes.add(DREADNOTH_SLAM);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
        slamTicks.remove(client.getTickCount());
        jellyTargets.clear();
        appliedHitsplats.clear();
        previousDreadnothArea = dreadnoth == null ? null : dreadnoth.getWorldArea();
    }

    private boolean isSlamHit(Raider raider) {
        if (!slamTicks.contains(client.getTickCount())) {
            return false;
        }

        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return raider.getPlayer().getOverheadIcon() != HeadIcon.MELEE;
    }

    private boolean isRangeHit(Raider raider) {
        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return rangeOverheadTracker.didMissPrayer(raider);
    }

    private boolean isBloodPoolHit(Raider raider) {
        WorldPoint location = raider.getPreviousWorldLocation();
        int tick = client.getTickCount();
        Integer spawnTick = bloodPools.get(location);
        if (spawnTick == null || spawnTick == tick) {
            return false;
        }

        Integer lastHitTick = lastBloodPoolHitTicks.get(raider.getName());
        if (lastHitTick != null && tick - lastHitTick < BLOOD_POOL_HIT_INTERVAL_IN_TICKS) {
            return false;
        }

        lastBloodPoolHitTicks.put(raider.getName(), tick);
        return true;
    }

    private boolean isInside(WorldPoint location) {
        // He's in the air from the start of a jump until he lands, and doesn't hurt anyone inside him until a tick later
        if (location == null || client.getTickCount() <= landingTick + INSIDE_DELAY_AFTER_LANDING_IN_TICKS ||
                isDreadnothDead) {
            return false;
        }

        return previousDreadnothArea != null && previousDreadnothArea.contains(location);
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (!(event.getActor() instanceof Player)) return;

        int type = event.getHitsplat().getHitsplatType();
        if (type == HitsplatID.HEAL || type == HitsplatID.POISON || type == HitsplatID.VENOM ||
                type == HitsplatID.DISEASE || type == HitsplatID.BURN) return;

        appliedHitsplats.addHitsplatForRaider(event.getActor().getName());
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        rangeOverheadTracker.onGameTick(client.getTickCount());
        landingHitTiles.onGameTick(client.getTickCount());
        bloodBallHitTiles.onGameTick(client.getTickCount());
        trackedBloodBalls.removeIf(projectile -> projectile.getRemainingCycles() <= 0);
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC)) return;

        NPC npc = (NPC) actor;
        if (npc.getId() == NpcID.TFA_JELLY_BOSS) {
            if (npc.getAnimation() == AnimationID.DREADNOTH_JUMP01) {
                onJump(JUMP_IN_PLACE_DURATION_IN_TICKS);
            } else if (npc.getAnimation() == AnimationID.DREADNOTH_JUMP02) {
                onJump(JUMP_DURATION_IN_TICKS);
            } else if (npc.getAnimation() == AnimationID.DREADNOTH_DEATH01) {
                onDreadnothDeath();
            }
        } else if (npc.getId() == NpcID.TFA_JELLY_MINION && npc.getAnimation() == AnimationID.JELLY_ATTACK &&
                npc.getInteracting() instanceof Player) {
            jellyTargets.add(npc.getInteracting().getName());
        }
    }

    private void onDreadnothDeath() {
        isDreadnothDead = true;
        deathTick = client.getTickCount();
        slamTicks.clear();
        landingHitTiles.clear();
        bloodBallHitTiles.clear();
        trackedBloodBalls.clear();
    }

    private void onJump(int durationInTicks) {
        int tick = client.getTickCount() + durationInTicks;
        slamTicks.add(tick);
        landingTick = Math.max(landingTick, tick);
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        if (event.getGraphicsObject().getId() != SpotanimID.TFA_BOSS_JELLY_5X5_JUMP) return;

        landingHitTiles.putAll(client.getTickCount() + JUMP_DURATION_IN_TICKS,
                computeTilesAround(getWorldPoint(event.getGraphicsObject()), LANDING_DISTANCE));
    }

    @Subscribe
    public void onProjectileMoved(ProjectileMoved event) {
        Projectile projectile = event.getProjectile();
        if (RANGE_ATTACKS.containsKey(projectile.getId())) {
            // He fires one last volley the tick after he starts dying
            if (!isDreadnothDead || client.getTickCount() <= deathTick + 1) {
                rangeOverheadTracker.trackProjectile(event, client.getTickCount());
            }
        } else if (projectile.getId() == SpotanimID.VFX_DREADNOTH_RANGED_PROJ02 &&
                trackedBloodBalls.add(projectile)) {
            bloodBallHitTiles.put(getActivationTick(projectile), projectile.getTargetPoint());
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_JELLY_BOSS_DAMAGE_TILE) {
            bloodPools.put(event.getGameObject().getWorldLocation(), client.getTickCount());
        }
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_JELLY_BOSS_DAMAGE_TILE) {
            bloodPools.remove(event.getGameObject().getWorldLocation());
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        if (event.getNpc().getId() == NpcID.TFA_JELLY_BOSS) {
            dreadnoth = event.getNpc();
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        if (event.getNpc() == dreadnoth) {
            dreadnoth = null;
        }
    }
}

package com.tfamistaketracker.detector.boss;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.BaseMistakeDetector;
import com.tfamistaketracker.detector.tracker.InstantHitTilesTracker;
import com.tfamistaketracker.detector.tracker.OverheadTracker;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.HeadIcon;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.OCELLUS;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P1_AUTO_ATTACK;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P1_SLAM;

/**
 * In phase 1, Ocellus fires magic and ranged projectiles that need the matching prayer when they hit, and his slam
 * explodes the floor around him the tick after his explode animation.
 */
@Slf4j
@Singleton
public class OcellusP1Detector extends BaseMistakeDetector {

    private static final Map<Integer, OverheadTracker.Attack> AUTO_ATTACKS = ImmutableMap.of(
            SpotanimID.VFX_OCELLUS_WATER_ATTACK01_PROJANIM,
            OverheadTracker.Attack.of(HeadIcon.MAGIC, OverheadTracker.PrayerCheck.HIT),
            SpotanimID.VFX_OCELLUS_FIRE_ATTACK01_PROJANIM,
            OverheadTracker.Attack.of(HeadIcon.RANGED, OverheadTracker.PrayerCheck.HIT));

    private static final Set<Integer> SLAM_GRAPHICS_IDS = ImmutableSet.of(
            SpotanimID.VFX_OCELLUS_P1_EXPLODE_FLOOR,
            SpotanimID.VFX_OCELLUS_P1_EXPLODE_FLOOR_90,
            SpotanimID.VFX_OCELLUS_P1_EXPLODE_FLOOR_180,
            SpotanimID.VFX_OCELLUS_P1_EXPLODE_FLOOR_270);

    private final OverheadTracker autoAttackOverheadTracker = new OverheadTracker(AUTO_ATTACKS);
    private final InstantHitTilesTracker slamHitTiles = new InstantHitTilesTracker();

    @Override
    public void cleanup() {
        autoAttackOverheadTracker.clear();
        slamHitTiles.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return OCELLUS;
    }

    // Every phase is the same Ocellus NPC changing form, so the phase is tracked from his id
    @Override
    public Integer getRequiredNpcId() {
        return NpcID.TFA_OCELLUS_P1;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        if (isAutoAttackHit(raider)) {
            mistakes.add(OCELLUS_P1_AUTO_ATTACK);
        }

        if (slamHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(OCELLUS_P1_SLAM);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
    }

    private boolean isAutoAttackHit(Raider raider) {
        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return autoAttackOverheadTracker.didMissPrayer(raider);
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        autoAttackOverheadTracker.onGameTick(client.getTickCount());
        slamHitTiles.onGameTick(client.getTickCount());
    }

    @Subscribe
    public void onProjectileMoved(ProjectileMoved event) {
        if (!AUTO_ATTACKS.containsKey(event.getProjectile().getId())) return;

        autoAttackOverheadTracker.trackProjectile(event, client.getTickCount());
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        if (!SLAM_GRAPHICS_IDS.contains(event.getGraphicsObject().getId())) return;

        slamHitTiles.add(getWorldPoint(event.getGraphicsObject()));
    }
}

package com.tfamistaketracker.detector.boss;

import com.google.common.collect.ImmutableSet;
import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.BaseMistakeDetector;
import com.tfamistaketracker.detector.tracker.DelayedHitTilesTracker;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.OCELLUS;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P2_PORTAL;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P2_PURPLE_TILE;

/**
 * In phase 2, lines of portals fire projectiles across each quadrant, hitting anyone who isn't on that call's safe
 * tiles as they pass. The safe tiles rotate, so instead of tracking them, a portal hit is any big hit shortly after
 * the portals fire. Purple tiles explode a few ticks after they appear.
 */
@Slf4j
@Singleton
public class OcellusP2Detector extends BaseMistakeDetector {

    private static final int MIN_PORTAL_HIT = 15;
    private static final int PORTAL_HIT_WINDOW_IN_TICKS = 2;
    private static final int PURPLE_TILE_HIT_DELAY_IN_TICKS = 4;

    private static final Set<Integer> NON_DAMAGE_HITSPLAT_IDS = ImmutableSet.of(HitsplatID.HEAL, HitsplatID.POISON,
            HitsplatID.VENOM, HitsplatID.DISEASE, HitsplatID.BURN);

    private int lastPortalSpawnTick;

    private final Set<Projectile> trackedPortalProjectiles = new HashSet<>();
    private final Set<String> bigHitRaiders = new HashSet<>();
    private final DelayedHitTilesTracker purpleHitTiles = new DelayedHitTilesTracker();

    public OcellusP2Detector() {
        lastPortalSpawnTick = -1;
    }

    @Override
    public void cleanup() {
        lastPortalSpawnTick = -1;
        trackedPortalProjectiles.clear();
        bigHitRaiders.clear();
        purpleHitTiles.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return OCELLUS;
    }

    // Every phase is the same Ocellus NPC changing form, so the phase is tracked from his id
    @Override
    public Integer getRequiredNpcId() {
        return NpcID.TFA_OCELLUS_P2;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        if (purpleHitTiles.getActiveHitTiles().contains(raider.getPreviousWorldLocation())) {
            mistakes.add(OCELLUS_P2_PURPLE_TILE);
        } else if (isPortalHit(raider)) {
            mistakes.add(OCELLUS_P2_PORTAL);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
        bigHitRaiders.clear();
    }

    private boolean isPortalHit(Raider raider) {
        return bigHitRaiders.contains(raider.getName()) && lastPortalSpawnTick >= 0 &&
                client.getTickCount() - lastPortalSpawnTick <= PORTAL_HIT_WINDOW_IN_TICKS;
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        purpleHitTiles.onGameTick(client.getTickCount());
        trackedPortalProjectiles.removeIf(projectile -> projectile.getRemainingCycles() <= 0);
    }

    @Subscribe
    public void onProjectileMoved(ProjectileMoved event) {
        if (event.getProjectile().getId() != SpotanimID.VFX_OCELLUS_PORTAL_PROJECTILE) return;

        if (trackedPortalProjectiles.add(event.getProjectile())) {
            lastPortalSpawnTick = client.getTickCount();
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (!(event.getActor() instanceof Player)) return;
        if (NON_DAMAGE_HITSPLAT_IDS.contains(event.getHitsplat().getHitsplatType())) return;

        if (event.getHitsplat().getAmount() >= MIN_PORTAL_HIT) {
            bigHitRaiders.add(event.getActor().getName());
        }
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        if (event.getGraphicsObject().getId() != SpotanimID.VFX_OCELLUS_P2_AOE_DODGE) return;

        purpleHitTiles.put(client.getTickCount() + PURPLE_TILE_HIT_DELAY_IN_TICKS,
                getWorldPoint(event.getGraphicsObject()));
    }
}

package com.tfamistaketracker.detector.boss;

