import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.OCELLUS;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P2_PURPLE_TILE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_AOE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_FALL;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_INSOLENCE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_MELEE_PARRY;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P4_PRAYER_ATTACK;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_VOID_FLARE_DETONATION;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_TANK_MAGE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_UNTETHER_EXPLOSION;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_UNTETHER_MAGE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P4_VOID_EXPLOSION;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P4_VOID_SPACE;
import static com.tfamistaketracker.TfaMistake.OCELLUS_P3_VOID_GRIEF;

/**
 * In phase 3, Ocellus slashes, drops void bombs that leave void floor behind, and explodes the arena after untethering:
 * first everything outside him, then under him a tick later. During his parry and his hybrid attack, raiders have to
 * pray correctly when the hits land, and rifts that aren't dealt with in time explode on everyone. After his range and
 * melee attacks, void explosions land on each raider's tile on a fixed schedule, and the tiles under him (range) or
 * away from him (melee) turn to space. If his target isn't in melee range he hits everyone with magic instead, which is
 * on the tank. Nothing counts once he starts dying.
 */
@Slf4j
@Singleton
public class OcellusP3Detector extends BaseMistakeDetector {

    private static final Set<Integer> VOID_GRIEF_GRAPHICS_IDS = ImmutableSet.of(
            SpotanimID.VFX_OCELLUS_QUADRANT_BOMB_IMPACT_01,
            SpotanimID.VFX_OCELLUS_QUADRANT_BOMB_DROP_01);

    private static final Map<Integer, HeadIcon> PRAYER_ATTACK_STYLES = ImmutableMap.of(
            SpotanimID.VFX_OCELLUS_PHASE3_MELEE_HYBRID, HeadIcon.MELEE,
            SpotanimID.VFX_OCELLUS_PHASE3_MELEE_HYBRID_MAGIC, HeadIcon.MAGIC,
            SpotanimID.VFX_OCELLUS_PHASE3_MELEE_HYBRID_RANGED, HeadIcon.RANGED);

    private static final Set<Integer> VOID_FLARE_DETONATION_ANIMATION_IDS = ImmutableSet.of(
            AnimationID.VFX_OCELLUS_VOIDFLARE_DEFAULT_DETONATE,
            AnimationID.VFX_OCELLUS_VOIDFLARE_HEAL_DETONATE,
            AnimationID.VFX_OCELLUS_VOIDFLARE_BUFF_DETONATE);

    // The parry hits 1 tick after it starts, then every 3 ticks from 5 ticks after, until it ends. Every raider gets a
    // hitsplat on each hit, so it only counts if they took damage.
    private static final int[] PARRY_HIT_OFFSETS = {1, 5, 8, 11};
    // Any other animation cuts the parry short, e.g. destroying a quadrant
    private static final Set<Integer> PARRY_ANIMATION_IDS = ImmutableSet.of(
            AnimationID.NPC_OCELLUS_PHASE3_PRAYER_IN,
            AnimationID.NPC_OCELLUS_PHASE3_PRAYER_LOOP,
            AnimationID.NPC_OCELLUS_PHASE3_PRAYER_OUT);
    private static final int PRAYER_ATTACK_HIT_DELAY_IN_TICKS = 5;
    private static final int PURPLE_TILE_HIT_DELAY_IN_TICKS = 4;
    private static final int VOID_FLOOR_HIT_DELAY_IN_TICKS = 2;
    // Ticks from his range or melee attack until it takes half of everyone's health
    private static final int RANGE_ATTACK_HIT_DELAY_IN_TICKS = 4;
    private static final int MELEE_ATTACK_HIT_DELAY_IN_TICKS = 1;
    // Void explosions land on the tile each raider stood on the tick before, then hurt them a tick later if they stayed
    private static final int FIRST_VOID_EXPLOSION_DELAY_IN_TICKS = 5;
    private static final int VOID_EXPLOSION_INTERVAL_IN_TICKS = 2;
    private static final int VOID_EXPLOSION_COUNT = 6;
    private static final int SPACE_DISTANCE = 1;
    // In case his end animation never plays. Space lasts 15-17 ticks after the hit.
    private static final int MAX_SPACE_DURATION_IN_TICKS = 18;
    private static final int UNTETHER_MAGE_HIT_DELAY_IN_TICKS = 4;
    private static final int MIN_UNDER_SLASH_HIT = 20;

    private static final Set<Integer> NON_DAMAGE_HITSPLAT_IDS = ImmutableSet.of(HitsplatID.HEAL, HitsplatID.POISON,
            HitsplatID.VENOM, HitsplatID.DISEASE, HitsplatID.BURN);
    private static final int VOID_FLOOR_HIT_INTERVAL_IN_TICKS = 2;

    private final InstantHitTilesTracker aoeHitTiles = new InstantHitTilesTracker();
    private final InstantHitTilesTracker insolenceHitTiles = new InstantHitTilesTracker();
    private final InstantHitTilesTracker voidGriefHitTiles = new InstantHitTilesTracker();
    private final DelayedHitTilesTracker purpleHitTiles = new DelayedHitTilesTracker();
    // Void floor tile -> tick it spawned. It starts hurting 2 ticks after it spawns.
    private final Map<WorldPoint, Integer> voidFloorTiles = new HashMap<>();
    // Raider name -> tick they were last hurt by the void floor. It can't hurt the same raider on back-to-back ticks.
    private final Map<String, Integer> lastVoidFloorHitTicks = new HashMap<>();

    // His slashes also cut through him, along the rows and columns they cover
    private NPC ocellus;

    private final Set<Integer> parryHitTicks = new HashSet<>();
    // Raider name -> their biggest hit this tick
    private final Map<String, Integer> raiderHits = new HashMap<>();
    private final Map<String, Integer> raiderHitCounts = new HashMap<>();
    // Hit tick -> the prayer needed for it
    private final Map<Integer, HeadIcon> prayerAttackHits = new HashMap<>();
    // The style is a spot anim on Ocellus, which is only certain by the end of the tick he starts the attack
    private NPC prayerAttacker;

    // Prayer against his magic counts when he starts casting, not when it lands
    private int tankMageTick;
    private String tankMageTank;

    private int untetherTick;
    private WorldArea untetherArea;
    // His untether's purple tiles also hit everyone with magic
    private boolean isUntethering;
    private final Set<Integer> untetherMageHitTicks = new HashSet<>();

    private final Set<Integer> voidExplosionTicks = new HashSet<>();
    // Raider name -> the tile the current void explosion landed on
    private final Map<String, WorldPoint> voidExplosionTiles = new HashMap<>();

    // -1 when there's no space. Range attacks make the tiles under him space, melee attacks everything else.
    private int spaceStartTick;
    private int spaceEndTick;
    private Set<WorldPoint> spaceArea;
    private boolean isSpaceInside;

    private int voidFlareDetonationCount;
    private final Set<String> fallingRaiders = new HashSet<>();

    public OcellusP3Detector() {
        tankMageTick = -1;
        untetherTick = -1;
        spaceStartTick = -1;
    }

    @Override
    public void startup() {
        super.startup();
        for (NPC npc : client.getTopLevelWorldView().npcs()) {
            if (npc.getId() == NpcID.TFA_OCELLUS_P3) {
                ocellus = npc;
            }
        }

        // Void floor can already be down when the phase starts
        Tile[][] tiles = client.getTopLevelWorldView().getScene().getTiles()[client.getTopLevelWorldView().getPlane()];
        for (Tile[] column : tiles) {
            for (Tile tile : column) {
                GroundObject groundObject = tile == null ? null : tile.getGroundObject();
                if (groundObject != null && groundObject.getId() == ObjectID.TFA_OCELLUS_VOID_DEGEN_BOMB) {
                    voidFloorTiles.put(groundObject.getWorldLocation(), client.getTickCount());
                }
            }
        }
    }

    @Override
    public void cleanup() {
        aoeHitTiles.clear();
        insolenceHitTiles.clear();
        voidGriefHitTiles.clear();
        purpleHitTiles.clear();
        voidFloorTiles.clear();
        lastVoidFloorHitTicks.clear();
        ocellus = null;
        parryHitTicks.clear();
        raiderHits.clear();
        raiderHitCounts.clear();
        prayerAttackHits.clear();
        prayerAttacker = null;
        tankMageTick = -1;
        tankMageTank = null;
        untetherTick = -1;
        untetherArea = null;
        isUntethering = false;
        untetherMageHitTicks.clear();
        voidExplosionTicks.clear();
        voidExplosionTiles.clear();
        spaceStartTick = -1;
        spaceArea = null;
        voidFlareDetonationCount = 0;
        fallingRaiders.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return OCELLUS;
    }

    // Every phase is the same Ocellus NPC changing form, so the phase is tracked from his id
    @Override
    public Integer getRequiredNpcId() {
        return NpcID.TFA_OCELLUS_P3;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        WorldPoint previousLocation = raider.getPreviousWorldLocation();
        int tick = client.getTickCount();

        if (voidGriefHitTiles.getActiveHitTiles().contains(previousLocation) || isVoidFloorHit(raider)) {
            mistakes.add(OCELLUS_P3_VOID_GRIEF);
        }

        if (isSlashHit(aoeHitTiles, raider)) {
            mistakes.add(OCELLUS_P3_AOE);
        }

        if (isSlashHit(insolenceHitTiles, raider)) {
            mistakes.add(OCELLUS_P3_INSOLENCE);
        }

        // A single hit on a space tile is the space, since the explosion only lands if they didn't move
        boolean isSpaceHit = isSpaceHit(raider);
        boolean isVoidExplosionHit = isVoidExplosionHit(raider) &&
                (!isSpaceHit || raiderHitCounts.getOrDefault(raider.getName(), 0) >= 2);
        if (isSpaceHit) {
            mistakes.add(OCELLUS_P4_VOID_SPACE);
        }

        if (isVoidExplosionHit) {
            mistakes.add(OCELLUS_P4_VOID_EXPLOSION);
        }
        if (voidExplosionTicks.contains(tick)) {
            voidExplosionTiles.put(raider.getName(), previousLocation);
        }

        if (purpleHitTiles.getActiveHitTiles().contains(previousLocation)) {
            mistakes.add(OCELLUS_P2_PURPLE_TILE);
        }

        HeadIcon prayerAttackStyle = prayerAttackHits.get(tick);
        if (prayerAttackStyle != null && isOffPrayer(raider, prayerAttackStyle)) {
            mistakes.add(OCELLUS_P4_PRAYER_ATTACK);
        }

        if (parryHitTicks.contains(tick) && raiderHits.containsKey(raider.getName()) &&
                isOffPrayer(raider, HeadIcon.MELEE)) {
            mistakes.add(OCELLUS_P3_MELEE_PARRY);
        }

        if (tick == tankMageTick && raider.getName().equals(tankMageTank) && isAnyoneOffMagic()) {
            mistakes.add(OCELLUS_P3_TANK_MAGE);
        }

        for (int i = 0; i < voidFlareDetonationCount; i++) {
            mistakes.add(OCELLUS_P3_VOID_FLARE_DETONATION);
        }

        if (isUntetherHit(previousLocation)) {
            mistakes.add(OCELLUS_P3_UNTETHER_EXPLOSION);
        }

        if (untetherMageHitTicks.contains(tick) && raiderHits.containsKey(raider.getName()) &&
                isOffPrayer(raider, HeadIcon.MAGIC)) {
            mistakes.add(OCELLUS_P3_UNTETHER_MAGE);
        }

        if (fallingRaiders.contains(raider.getName())) {
            mistakes.add(OCELLUS_P3_FALL);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
        int tick = client.getTickCount();
        parryHitTicks.remove(tick);
        prayerAttackHits.remove(tick);
        raiderHits.clear();
        raiderHitCounts.clear();
        untetherMageHitTicks.remove(tick);
        if (voidExplosionTicks.remove(tick - 1)) {
            voidExplosionTiles.clear();
        }
        voidFlareDetonationCount = 0;
        fallingRaiders.clear();
    }

    private boolean isOffPrayer(Raider raider, HeadIcon requiredHeadIcon) {
        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return raider.getPlayer().getOverheadIcon() != requiredHeadIcon;
    }

    // His magic hits everyone, so it's only a mistake if someone isn't protected from it
    private boolean isAnyoneOffMagic() {
        return raidState.getRaiders().values().stream()
                .anyMatch(r -> !r.isDead() && r.getPlayer().getOverheadIcon() != HeadIcon.MAGIC);
    }

    private boolean isSlashHit(InstantHitTilesTracker slashHitTiles, Raider raider) {
        WorldPoint location = raider.getPreviousWorldLocation();
        if (location == null) {
            return false;
        }

        Set<WorldPoint> hitTiles = slashHitTiles.getActiveHitTiles();
        if (hitTiles.contains(location)) {
            return true;
        }

        // Under him is worked out rather than shown, so only count it if it hurt
        if (ocellus == null || !ocellus.getWorldArea().contains(location) ||
                raiderHits.getOrDefault(raider.getName(), 0) < MIN_UNDER_SLASH_HIT) {
            return false;
        }
        return hitTiles.stream().anyMatch(tile -> tile.getX() == location.getX() || tile.getY() == location.getY());
    }

    private boolean isVoidExplosionHit(Raider raider) {
        WorldPoint explosionTile = voidExplosionTiles.get(raider.getName());
        return voidExplosionTicks.contains(client.getTickCount() - 1) && explosionTile != null &&
                explosionTile.equals(raider.getPreviousWorldLocation()) && raiderHits.containsKey(raider.getName());
    }

    private boolean isSpaceHit(Raider raider) {
        int tick = client.getTickCount();
        if (spaceArea == null || tick < spaceStartTick || tick >= spaceEndTick || raider.getPreviousWorldLocation() == null) {
            return false;
        }

        return spaceArea.contains(raider.getPreviousWorldLocation()) == isSpaceInside &&
                raiderHits.containsKey(raider.getName());
    }

    private void onSiphon(NPC npc, int hitDelay, boolean isSpaceInside) {
        int hitTick = client.getTickCount() + hitDelay;
        for (int i = 0; i < VOID_EXPLOSION_COUNT; i++) {
            voidExplosionTicks.add(hitTick + FIRST_VOID_EXPLOSION_DELAY_IN_TICKS + i * VOID_EXPLOSION_INTERVAL_IN_TICKS);
        }

        spaceStartTick = hitTick + 1;
        spaceEndTick = hitTick + MAX_SPACE_DURATION_IN_TICKS;
        spaceArea = computeTilesAround(npc.getWorldArea(), SPACE_DISTANCE);
        this.isSpaceInside = isSpaceInside;
    }

    private boolean isVoidFloorHit(Raider raider) {
        int tick = client.getTickCount();
        Integer spawnTick = voidFloorTiles.get(raider.getPreviousWorldLocation());
        if (spawnTick == null || tick - spawnTick < VOID_FLOOR_HIT_DELAY_IN_TICKS) {
            return false;
        }

        Integer lastHitTick = lastVoidFloorHitTicks.get(raider.getName());
        if (lastHitTick != null && tick - lastHitTick < VOID_FLOOR_HIT_INTERVAL_IN_TICKS) {
            return false;
        }

        lastVoidFloorHitTicks.put(raider.getName(), tick);
        return true;
    }

    private boolean isUntetherHit(WorldPoint location) {
        if (untetherArea == null || location == null) {
            return false;
        }

        // Everything outside him explodes first, then under him a tick later
        int tick = client.getTickCount();
        if (tick == untetherTick) {
            return !untetherArea.contains(location);
        } else if (tick == untetherTick + 1) {
            return untetherArea.contains(location);
        }
        return false;
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        int tick = client.getTickCount();
        aoeHitTiles.onGameTick(tick);
        insolenceHitTiles.onGameTick(tick);
        voidGriefHitTiles.onGameTick(tick);
        purpleHitTiles.onGameTick(tick);

        if (prayerAttacker != null) {
            for (Map.Entry<Integer, HeadIcon> style : PRAYER_ATTACK_STYLES.entrySet()) {
                if (prayerAttacker.hasSpotAnim(style.getKey())) {
                    prayerAttackHits.put(tick + PRAYER_ATTACK_HIT_DELAY_IN_TICKS, style.getValue());
                }
            }
            prayerAttacker = null;
        }
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        Actor actor = event.getActor();
        if (actor instanceof Player) {
            if (actor.getAnimation() == AnimationID.TFA_OCELLUS_VOID_PLAYER_DEATH) {
                fallingRaiders.add(actor.getName());
            }
            return;
        }

        if (!(actor instanceof NPC)) return;

        NPC npc = (NPC) actor;
        int tick = client.getTickCount();
        if (VOID_FLARE_DETONATION_ANIMATION_IDS.contains(npc.getAnimation())) {
            voidFlareDetonationCount++;
        } else if (npc.getId() != NpcID.TFA_OCELLUS_P3) {
            return;
        }

        ocellus = npc;
        if (npc.getAnimation() != -1 && !PARRY_ANIMATION_IDS.contains(npc.getAnimation())) {
            parryHitTicks.removeIf(hitTick -> hitTick > tick);
        }

        if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_DEATH) {
            shutdown();
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_PRAYER_IN) {
            for (int offset : PARRY_HIT_OFFSETS) {
                parryHitTicks.add(tick + offset);
            }
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_PRAYER_OUT) {
            parryHitTicks.removeIf(hitTick -> hitTick > tick);
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_DEFLECT_IN) { // His range attack
            onSiphon(npc, RANGE_ATTACK_HIT_DELAY_IN_TICKS, true);
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_SOUL_FRAGMENT_START) { // His melee attack
            onSiphon(npc, MELEE_ATTACK_HIT_DELAY_IN_TICKS, false);
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_DEFLECT_OUT ||
                npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_SOUL_FRAGMENT_END) {
            spaceArea = null;
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_MELEE_HYBRID) {
            prayerAttacker = npc;
            spaceArea = null;
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_BASIC_PROJECTILE_ALL &&
                npc.getInteracting() instanceof Player) {
            tankMageTick = tick;
            tankMageTank = npc.getInteracting().getName();
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_UNLEASH_IN) {
            isUntethering = true;
        } else if (npc.getAnimation() == AnimationID.NPC_OCELLUS_PHASE3_UNLEASH_OUT) {
            untetherTick = tick;
            untetherArea = npc.getWorldArea();
            isUntethering = false;
        }
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        GraphicsObject graphicsObject = event.getGraphicsObject();
        WorldPoint tile = getWorldPoint(graphicsObject);
        if (graphicsObject.getId() == SpotanimID.VFX_OCELLUS_P3_SHADOW_SLASH_SPOTANIM01) {
            aoeHitTiles.add(tile);
        } else if (graphicsObject.getId() == SpotanimID.VFX_OCELLUS_P3_SHADOW_SLASH_SUPERIOR_SPOTANIM01) {
            insolenceHitTiles.add(tile);
        } else if (VOID_GRIEF_GRAPHICS_IDS.contains(graphicsObject.getId())) {
            voidGriefHitTiles.add(tile);
        } else if (graphicsObject.getId() == SpotanimID.VFX_OCELLUS_P2_AOE_DODGE) {
            purpleHitTiles.put(client.getTickCount() + PURPLE_TILE_HIT_DELAY_IN_TICKS, tile);
            if (isUntethering) {
                untetherMageHitTicks.add(client.getTickCount() + UNTETHER_MAGE_HIT_DELAY_IN_TICKS);
            }
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (!(event.getActor() instanceof Player)) return;
        if (NON_DAMAGE_HITSPLAT_IDS.contains(event.getHitsplat().getHitsplatType())) return;

        int amount = event.getHitsplat().getAmount();
        if (amount > 0) {
            raiderHits.merge(event.getActor().getName(), amount, Math::max);
            raiderHitCounts.merge(event.getActor().getName(), 1, Integer::sum);
        }
    }

    @Subscribe
    public void onActorDeath(ActorDeath event) {
        if (event.getActor() instanceof NPC && ((NPC) event.getActor()).getId() == NpcID.TFA_OCELLUS_P3) {
            shutdown();
        }
    }

    @Subscribe
    public void onGroundObjectSpawned(GroundObjectSpawned event) {
        if (event.getGroundObject().getId() == ObjectID.TFA_OCELLUS_VOID_DEGEN_BOMB) {
            voidFloorTiles.put(event.getGroundObject().getWorldLocation(), client.getTickCount());
        }
    }

    @Subscribe
    public void onGroundObjectDespawned(GroundObjectDespawned event) {
        if (event.getGroundObject().getId() == ObjectID.TFA_OCELLUS_VOID_DEGEN_BOMB) {
            voidFloorTiles.remove(event.getGroundObject().getWorldLocation());
        }
    }
}

package com.tfamistaketracker.detector.boss;

import com.tfamistaketracker.RaidRoom;
import com.tfamistaketracker.Raider;
import com.tfamistaketracker.TfaMistake;
import com.tfamistaketracker.detector.BaseMistakeDetector;
import com.tfamistaketracker.detector.tracker.DelayedHitTilesTracker;
import com.tfamistaketracker.detector.tracker.InstantHitTilesTracker;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.GraphicsObject;
import net.runelite.api.HeadIcon;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static com.tfamistaketracker.RaidRoom.XARTH;
import static com.tfamistaketracker.TfaMistake.XARTH_CORPSE_HEAL;
import static com.tfamistaketracker.TfaMistake.XARTH_EXPLOSION;
import static com.tfamistaketracker.TfaMistake.XARTH_FIRE;
import static com.tfamistaketracker.TfaMistake.XARTH_MELEE;
import static com.tfamistaketracker.TfaMistake.XARTH_TETHER;

/**
 * Xarth's tether marks each raider's tile and hits them a few ticks later if they're still on it. His flame blast
 * explodes most of the arena except behind cover, both after a tether and when corpses reach him and heal him. Fire
 * left on the floor burns anyone standing on it, and later in the fight he slashes whoever he's attacking.
 */
@Slf4j
@Singleton
public class XarthDetector extends BaseMistakeDetector {

    // Fire still burns while he's dying, so mistakes only stop once he's gone
    private boolean isXarthDead;
    private int corpseHealCount;

    private final DelayedHitTilesTracker tetherHitTiles = new DelayedHitTilesTracker();
    private final InstantHitTilesTracker explosionHitTiles = new InstantHitTilesTracker();
    // Fire tile -> tick it spawned. Fire doesn't burn on the tick it spawns.
    private final Map<WorldPoint, Integer> fireTiles = new HashMap<>();
    private final Set<String> meleeTargets = new HashSet<>();

    public XarthDetector() {
        isXarthDead = false;
        corpseHealCount = 0;
    }

    @Override
    public void cleanup() {
        isXarthDead = false;
        clearTrackers();
        fireTiles.clear();
    }

    private void clearTrackers() {
        corpseHealCount = 0;
        tetherHitTiles.clear();
        explosionHitTiles.clear();
        meleeTargets.clear();
    }

    @Override
    public RaidRoom getRaidRoom() {
        return XARTH;
    }

    @Override
    public List<TfaMistake> detectMistakes(@NonNull Raider raider) {
        List<TfaMistake> mistakes = new ArrayList<>();
        if (isXarthDead) {
            return mistakes;
        }

        WorldPoint previousLocation = raider.getPreviousWorldLocation();

        if (isOnFire(previousLocation)) {
            mistakes.add(XARTH_FIRE);
        }

        if (isMeleeHit(raider)) {
            mistakes.add(XARTH_MELEE);
        }

        if (tetherHitTiles.getActiveHitTiles().contains(previousLocation)) {
            mistakes.add(XARTH_TETHER);
        }

        if (explosionHitTiles.getActiveHitTiles().contains(previousLocation)) {
            mistakes.add(XARTH_EXPLOSION);
        }

        for (int i = 0; i < corpseHealCount; i++) {
            mistakes.add(XARTH_CORPSE_HEAL);
        }

        return mistakes;
    }

    @Override
    public void afterDetect() {
        meleeTargets.clear();
        corpseHealCount = 0;
    }

    private boolean isOnFire(WorldPoint location) {
        Integer spawnTick = fireTiles.get(location);
        return spawnTick != null && spawnTick != client.getTickCount();
    }

    private boolean isMeleeHit(Raider raider) {
        if (!meleeTargets.contains(raider.getName())) {
            return false;
        }

        if (vengeanceTracker.didPopVengeance(raider)) {
            return false;
        }

        return raider.getPlayer().getOverheadIcon() != HeadIcon.MELEE;
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        tetherHitTiles.onGameTick(client.getTickCount());
        explosionHitTiles.onGameTick(client.getTickCount());
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event) {
        Actor actor = event.getActor();
        if (!(actor instanceof NPC) || isXarthDead) return;

        NPC npc = (NPC) actor;
        if (npc.getId() == NpcID.TFA_XARTH) {
            if (npc.getAnimation() == AnimationID.XARTH_ATTACK_MELEE_01 &&
                    npc.getInteracting() instanceof Player) {
                meleeTargets.add(npc.getInteracting().getName());
            }
        } else if (npc.getId() == NpcID.TFA_XARTH_CORPSE && npc.getAnimation() == AnimationID.XARTH_CORPSE_ABSORBED_01) {
            corpseHealCount++;
        }
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        if (isXarthDead) return;

        GraphicsObject graphicsObject = event.getGraphicsObject();
        if (graphicsObject.getId() == SpotanimID.VFX_XARTH_AOE_HITANIM_01) {
            // The hit lands when the graphic starts
            tetherHitTiles.put(getActivationTick(graphicsObject, 0), getWorldPoint(graphicsObject));
        } else if (graphicsObject.getId() == SpotanimID.VFX_VMQ4_ENNIUS_FIRE_EXPLOSION) {
            explosionHitTiles.add(getWorldPoint(graphicsObject));
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        if (event.getNpc().getId() == NpcID.TFA_XARTH) {
            isXarthDead = true;
            clearTrackers();
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_XARTH_ARENAFIRE) {
            fireTiles.put(event.getGameObject().getWorldLocation(), client.getTickCount());
        }
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event) {
        if (event.getGameObject().getId() == ObjectID.TFA_XARTH_ARENAFIRE) {
            fireTiles.remove(event.getGameObject().getWorldLocation());
        }
    }
}

